// Profile-picture validation (pure). Run on the server BEFORE anything is decoded or stored.
//
// A picture is accepted only if its size is within the limit, its leading bytes identify a JPEG, PNG
// or WebP image, and any declared MIME type / file extension agree with that. The accepted bytes are
// then decoded and RE-ENCODED (./image.ts) to a small square WebP with no metadata, so what is stored
// is always a fresh image generated by the server, never the uploaded file. SVG, GIF and anything
// else cannot be accepted.
import { detectType, extensionOf, FILE_TYPES } from "../attachments/policy";

export const AVATAR_MAX_UPLOAD_BYTES = 2 * 1024 * 1024;
export const AVATAR_SIZE_PX = 256;
export const AVATAR_STORED_MIME = "image/webp";
export const AVATAR_SOURCE_MIMES = ["image/jpeg", "image/png", "image/webp"] as const;
/** For the file input's `accept` attribute (a convenience only; the server decides). */
export const AVATAR_ACCEPT = AVATAR_SOURCE_MIMES.join(",");

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

export type AvatarState = { readonly ok: boolean; readonly message?: string };
export type AvatarCandidate = { readonly name: string; readonly declaredMime: string; readonly bytes: Uint8Array };
export type AvatarVerdict = { readonly ok: true; readonly mime: string } | { readonly ok: false; readonly error: string };

function typeOf(mime: string) {
  return FILE_TYPES.find((t) => t.mime === mime);
}

export function validateAvatar(file: AvatarCandidate): AvatarVerdict {
  if (file.bytes.length === 0) return { ok: false, error: "Choose an image file." };
  if (file.bytes.length > AVATAR_MAX_UPLOAD_BYTES) return { ok: false, error: "The image is too large (limit 2 MB)." };
  const detected = detectType(file.bytes);
  if (detected === null || !(AVATAR_SOURCE_MIMES as readonly string[]).includes(detected)) {
    return { ok: false, error: "Use a JPEG, PNG or WebP image." };
  }
  const type = typeOf(detected);
  const declared = file.declaredMime.trim().toLowerCase();
  if (declared !== "" && declared !== "application/octet-stream" && declared !== detected && !type?.aliases.includes(declared)) {
    return { ok: false, error: "The file's type does not match its content." };
  }
  const ext = extensionOf(file.name);
  if (ext !== "" && !type?.extensions.includes(ext)) {
    return { ok: false, error: "The file name does not match an image of that type." };
  }
  return { ok: true, mime: detected };
}

/** "<profile id>/<random id>": the only object name the database and Storage policies accept. */
export function avatarObjectPath(profileId: string, objectId: string): string | null {
  return UUID.test(profileId) && UUID.test(objectId) ? `${profileId}/${objectId}` : null;
}

/** Up to two initials for the default avatar. Never empty. */
export function initials(name: string): string {
  const words = name.replace(/\s+/g, " ").trim().split(" ").filter(Boolean);
  const letters = (words.length > 1 ? [words[0], words[words.length - 1]] : words)
    .map((w) => Array.from(w ?? "").find((c) => /\p{L}|\p{N}/u.test(c)) ?? "")
    .join("")
    .toUpperCase();
  return letters === "" ? "?" : letters;
}
